    "m9ef29c88d7e8": "Ver fluxo da equipe",
    "m50f55dbef720": "Carregando membros",
    "m97f083027843": "expirou recentemente",
    "m0fb688b74cfb": "água corrente",
    "m38c6ee8a0034": "recuperação parcial",
    "m77d7b6fb827a": "Leve de volta tudo",
    "m7904fd5b0d29": "Atribuir pontos à equipe",
    "m38eefacbb326": "7 dias",
    "m84ad2952a308": "30 dias",
    "ma953fd81881f": "Data personalizada",
    "m7589d263a38d": "data de validade",
    "m2dd50f9d7818": "Confirmar alocação",
    "m54fa2e1046df": "Recuperação parcial de pontos",
    "m6df9d27b8aa2": "O valor especificado será retirado dos pontos de equipe restantes atuais do membro, sendo dada prioridade aos pontos não utilizados expirados mais recentemente.",
    "me0f80fccbad6": "Número de pontos recuperados",
    "m05e93a1aefe1": "Insira os pontos que deseja recuperar",
    "m6f3e052e50b2": "Atualmente recuperável: {value1}",
    "m7851cbb5dbf8": "Recuperando",
