    "mf29f83b86aeb": "Fluxo de pontos da equipe",
    "m267c4a7a86dd": "Todos os tipos",
    "m80716311485a": "consumo",
    "m6923cef57f25": "pegar de volta",
    "m1f29b74ad60c": "Expiração",
    "m631f1fc6bf92": "Fluxo de carregamento",
    "m85ad0e047775": "Total de {value1} itens",
    "m2338b87b9c2b": "Algumas fotos excedem o limite de 30 MB e foram filtradas automaticamente ({value1} fotos)",
    "m3333f1501053": "Somente {value1} fotos podem ser carregadas no máximo, as primeiras {value2} fotos foram selecionadas",
    "ma8f60f0523a2": "Faça login antes de usar a função de geração de imagens. Registre novos usuários para ganhar pontos de bônus!",
